fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let p = len - (len % 3); // Process up to the largest multiple of 3
    let mut res = Vec::with_capacity(len);
    
    for i in 0..p {
        match i % 3 {
            0 => res.push(s[i + 2]),  // Position 0 gets element from position 2
            1 => res.push(s[i - 1]),  // Position 1 gets element from position 0
            _ => res.push(s[i - 2]),  // Position 2 gets element from position 1
        }
    }
    
    // Copy the remaining elements unchanged
    for i in p..len {
        res.push(s[i]);
    }
    
    res
}